      "name": "updateModeRespawn",
      "fn": "sceneUpdateModeRespawn",
      "line": 6363,
      "source": "private updateModeRespawn(dt: number): void {\n    const pr = this.pendingRespawn!;\n    const fx = this.modeDef().respawnFx ?? FADE_DEFAULTS;\n    pr.t += dt;\n    if (pr.phase === 'out') {\n      this.screenFade = Math.min(1, pr.t / Math.max(0.01, fx.fadeOutSec));\n      if (pr.t >= fx.fadeOutSec + fx.holdSec) {\n        this.performModeRespawn();\n        pr.phase = 'in';\n        pr.t = 0;\n      }\n    } else {\n      this.screenFade = Math.max(0, 1 - pr.t / Math.max(0.01, fx.fadeInSec));\n      if (pr.t >= fx.fadeInSec) { this.pendingRespawn = null; this.screenFade = 0; }\n    }\n  }",
      "output": "export function sceneUpdateModeRespawn(nativeHost:NativeSceneCampaignFrameClosureHost, dt: number): void {\n    const pr = nativeHost.pendingRespawn!;\n    const fx = nativeHost.modeDef().respawnFx ?? FADE_DEFAULTS;\n    pr.t += dt;\n    if (pr.phase === 'out') {\n      nativeHost.screenFade = Math.min(1, pr.t / Math.max(0.01, fx.fadeOutSec));\n      if (pr.t >= fx.fadeOutSec + fx.holdSec) {\n        nativeHost.performModeRespawn();\n        pr.phase = 'in';\n        pr.t = 0;\n      }\n    } else {\n      nativeHost.screenFade = Math.max(0, 1 - pr.t / Math.max(0.01, fx.fadeInSec));\n      if (pr.t >= fx.fadeInSec) { nativeHost.pendingRespawn = null; nativeHost.screenFade = 0; }\n    }\n  }",
