      "line": 41643,
      "source": "restockVendor(): void {\n    const beat = this.restockOrdinal();\n    const smith = this.actors.find(a => this.hasNpcRole(a, 'vendor') && !a.dead);\n    if (smith) {\n      this.syncHoldIdx('brandt', this.vendorStock);\n      this.vendorStock = this.armVendorStock('brandt');\n      this.vendorArmedBeat['brandt'] = beat;\n      this.text(smith.pos, `${smith.name ?? 'The vendor'} restocks the wares.`, '#e8c87a', 13);\n    }\n    const chandler = this.actors.find(a => this.hasNpcRole(a, 'chandler') && !a.dead);\n    if (chandler) {\n      this.syncHoldIdx('chandler', this.chandlerStock);\n      this.chandlerStock = this.armVendorStock('chandler');\n      this.vendorArmedBeat['chandler'] = beat;\n      if (!smith) this.text(chandler.pos, `${chandler.name ?? 'The chandler'} restocks the wares.`, '#c8b06e', 13);\n    }\n    this.vendorRestockAt = (beat + 1) * this.restockSeconds();\n    if (this.localSeat.keeper) this.armBuyerShelves(true); // THE SHELF PER BUYER: every buyer here restocks with the counter\n  }",
      "output": "export function sceneRestockVendor(nativeHost:NativeSceneCampaignFrameClosureHost): void {\n    const beat = nativeHost.restockOrdinal();\n    const smith = nativeHost.actors.find(a => nativeHost.hasNpcRole(a, 'vendor') && !a.dead);\n    if (smith) {\n      nativeHost.syncHoldIdx('brandt', nativeHost.vendorStock);\n      nativeHost.vendorStock = nativeHost.armVendorStock('brandt');\n      nativeHost.vendorArmedBeat['brandt'] = beat;\n      nativeHost.text(smith.pos, `${smith.name ?? 'The vendor'} restocks the wares.`, '#e8c87a', 13);\n    }\n    const chandler = nativeHost.actors.find(a => nativeHost.hasNpcRole(a, 'chandler') && !a.dead);\n    if (chandler) {\n      nativeHost.syncHoldIdx('chandler', nativeHost.chandlerStock);\n      nativeHost.chandlerStock = nativeHost.armVendorStock('chandler');\n      nativeHost.vendorArmedBeat['chandler'] = beat;\n      if (!smith) nativeHost.text(chandler.pos, `${chandler.name ?? 'The chandler'} restocks the wares.`, '#c8b06e', 13);\n    }\n    nativeHost.vendorRestockAt = (beat + 1) * nativeHost.restockSeconds();\n    if (nativeHost.localSeat.keeper) nativeHost.armBuyerShelves(true); // THE SHELF PER BUYER: every buyer here restocks with the counter\n  }",
