      "source": "private updateHarborBoard(dt: number): void {\n    const engaged = this.nearHarborBoard();\n    this.harborGate.rearmIfWilled([this.localSeat]); // THE SHIMMY LAW\n    if (!this.harborGate.fire(engaged && this.playerIdle(), !!engaged, dt, CARAVAN_DWELL)) return;\n    this.harborDwellRequested = true;\n  }",
      "output": "export function sceneUpdateHarborBoard(nativeHost:NativeSceneCampaignFrameClosureHost, dt: number): void {\n    const engaged = nativeHost.nearHarborBoard();\n    nativeHost.harborGate.rearmIfWilled([nativeHost.localSeat]); // THE SHIMMY LAW\n    if (!nativeHost.harborGate.fire(engaged && nativeHost.playerIdle(), !!engaged, dt, CARAVAN_DWELL)) return;\n    nativeHost.harborDwellRequested = true;\n  }",
      "sourceSha256": "e5713280a1da2144d1538bc7ec4c860241f4f54959aba29338f47ffbddc5ef89",
