      "source": "private updateSail(dt: number): void {\n    const dock = this.portDock();\n    const engaged = !!dock && dist(this.player.pos, dock.pos) <= 110\n      && this.dwellReachable(this.player.pos, dock.pos, DWELL_CFG.reach, this.storyPair(this.player, dock));\n    this.sailGate.rearmIfWilled([this.localSeat]); // THE SHIMMY LAW\n    if (!this.sailGate.fire(engaged && this.canSail() && this.playerIdle(), engaged, dt, CARAVAN_DWELL)) return;\n    this.enterSailing();\n  }",
      "output": "export function sceneUpdateSail(nativeHost:NativeSceneCampaignFrameClosureHost, dt: number): void {\n    const dock = nativeHost.portDock();\n    const engaged = !!dock && dist(nativeHost.player.pos, dock.pos) <= 110\n      && nativeHost.dwellReachable(nativeHost.player.pos, dock.pos, DWELL_CFG.reach, nativeHost.storyPair(nativeHost.player, dock));\n    nativeHost.sailGate.rearmIfWilled([nativeHost.localSeat]); // THE SHIMMY LAW\n    if (!nativeHost.sailGate.fire(engaged && nativeHost.canSail() && nativeHost.playerIdle(), engaged, dt, CARAVAN_DWELL)) return;\n    nativeHost.enterSailing();\n  }",
