      "name": "updateSalvage",
      "fn": "sceneUpdateSalvage",
      "line": 20770,
      "source": "private updateSalvage(dt: number): void {\n    // Any LOCAL hand at the bench holds the latch; the first idle one fires\n    // (local hero checked first — solo is order-identical, see localHumanSeats).\n    const near = this.localHumanSeats().filter(s =>\n      !s.actor.dead && !s.actor.downed && this.nearSalvage(s));\n    if (this.salvageGate.rearmIfWilled(near)) this.stationArmed.add('salvage'); // THE SHIMMY LAW\n    const armed = this.stationDwellArmed('salvage', near.length > 0);\n    const ready = near.find(s => this.seatIdle(s));\n    if (!this.salvageGate.fire(!!ready && armed, near.length > 0 && armed, dt, SALVAGE_CFG.stationDwell)) return;\n    this.salvageDwellRequested = true;\n    this.salvageDwellSeatId = ready!.id;\n  }",
      "output": "export function sceneUpdateSalvage(nativeHost:NativeSceneCampaignFrameClosureHost, dt: number): void {\n    // Any LOCAL hand at the bench holds the latch; the first idle one fires\n    // (local hero checked first — solo is order-identical, see localHumanSeats).\n    const near = nativeHost.localHumanSeats().filter(s =>\n      !s.actor.dead && !s.actor.downed && nativeHost.nearSalvage(s));\n    if (nativeHost.salvageGate.rearmIfWilled(near)) nativeHost.stationArmed.add('salvage'); // THE SHIMMY LAW\n    const armed = nativeHost.stationDwellArmed('salvage', near.length > 0);\n    const ready = near.find(s => nativeHost.seatIdle(s));\n    if (!nativeHost.salvageGate.fire(!!ready && armed, near.length > 0 && armed, dt, SALVAGE_CFG.stationDwell)) return;\n    nativeHost.salvageDwellRequested = true;\n    nativeHost.salvageDwellSeatId = ready!.id;\n  }",
