      "source": "withBuyer<T>(seat: Seat, fn: () => T): T {\n    if (!this.localSeat.keeper || seat.keeper || seat.merc) return fn();\n    const was = this.shelfBuyer;\n    this.shelfBuyer = seat;\n    try { return fn(); } finally { this.shelfBuyer = was; }\n  }",
