      "source": "mireilleLessonLived(): boolean {\n    return (this.account.ledger[LEDGER_FLASK_LESSON] ?? 0) >= 1\n      || (this.ledger[MIREILLE_FILL_LEDGER] ?? 0) >= 1\n      || (this.ledger[MIREILLE_LESSON_LEDGER] ?? 0) >= 1;\n  }",
      "output": "export function sceneMireilleLessonLived(nativeHost:NativeSceneCampaignFrameClosureHost): boolean {\n    return (nativeHost.account.ledger[LEDGER_FLASK_LESSON] ?? 0) >= 1\n      || (nativeHost.ledger[MIREILLE_FILL_LEDGER] ?? 0) >= 1\n      || (nativeHost.ledger[MIREILLE_LESSON_LEDGER] ?? 0) >= 1;\n  }",
      "sourceSha256": "f73dd1508737305cfbb3861799b788a905d0d708dad38763d5c87a85dfc07e76",
