      "source": "private mireilleLessonStep(): 'learn' | null {\n    for (const s of MIREILLE_LESSON_STEPS) if (s.pendingSkills(this).length) return s.id;\n    return null;\n  }",
      "output": "export function sceneMireilleLessonStep(nativeHost:NativeSceneCampaignFrameClosureHost): 'learn' | null {\n    for (const s of MIREILLE_LESSON_STEPS) if (s.pendingSkills(nativeHost).length) return s.id;\n    return null;\n  }",
