      "line": 20760,
      "source": "nearSalvage(seat: Seat = this.localSeat): boolean {\n    const a = this.stationAnchor('salvage'); // THE ANCHORED DWELL: the bench slab\n    return this.hasSalvage() && !!a\n      && dist(seat.actor.pos, a.pos) <= SALVAGE_CFG.stationRadius\n      && this.dwellReachable(seat.actor.pos, a.pos, DWELL_CFG.reach, { from: seat.actor.tier ?? 0, to: a.tier });\n  }",
      "output": "export function sceneNearSalvage(nativeHost:NativeSceneCampaignFrameClosureHost, seat: Seat = nativeHost.localSeat): boolean {\n    const a = nativeHost.stationAnchor('salvage'); // THE ANCHORED DWELL: the bench slab\n    return nativeHost.hasSalvage() && !!a\n      && dist(seat.actor.pos, a.pos) <= SALVAGE_CFG.stationRadius\n      && nativeHost.dwellReachable(seat.actor.pos, a.pos, DWELL_CFG.reach, { from: seat.actor.tier ?? 0, to: a.tier });\n  }",
