      "source": "lightwellDoodads(): readonly Doodad[] {\n    if (this.wellArr !== this.doodads || this.wellLen !== this.doodads.length\n      || this.wellRev !== this.doodadsRev) {\n      this.wells = this.doodads.filter(d => !!lightwellOf(d.kind));\n      this.wellArr = this.doodads;\n      this.wellLen = this.doodads.length;\n      this.wellRev = this.doodadsRev;\n    }\n    return this.wells;\n  }",
      "output": "export function sceneLightwellDoodads(nativeHost:NativeSceneCampaignFrameClosureHost): readonly Doodad[] {\n    if (nativeHost.wellArr !== nativeHost.doodads || nativeHost.wellLen !== nativeHost.doodads.length\n      || nativeHost.wellRev !== nativeHost.doodadsRev) {\n      nativeHost.wells = nativeHost.doodads.filter(d => !!lightwellOf(d.kind));\n      nativeHost.wellArr = nativeHost.doodads;\n      nativeHost.wellLen = nativeHost.doodads.length;\n      nativeHost.wellRev = nativeHost.doodadsRev;\n    }\n    return nativeHost.wells;\n  }",
