      "source": "grantSkillGemItem(seat: Seat, inst: SkillInstance, spill = false): ItemInstance | null {\n    const item = makeSkillGemItem(inst);\n    if (!autoPlace(seat.meta.items, item)) {\n      if (spill) {\n        this.drops.push({\n          pos: this.clampPos(vec(seat.actor.pos.x + rand(-14, 14), seat.actor.pos.y + rand(-14, 14)), 10, undefined,\n            seat.actor.tier >= 1 ? { tier: seat.actor.tier } : undefined),\n          item: { kind: 'skill', inst }, bob: rand(0, Math.PI * 2), tier: seat.actor.tier, // THE SPOILS STORY: at the seat's feet\n        });\n        this.seatNote(seat, seat.actor.pos, 'your pack is full — it falls at your feet', '#c08a68', 12);\n        return null;\n      }\n      this.failNote(seat.actor, 'bagfull', 'inventory full');\n      return null;\n    }\n    this.markMetaDirty(seat);\n    return item;\n  }",
      "output": "export function sceneGrantSkillGemItem(nativeHost:NativeSceneCampaignFrameClosureHost, seat: Seat, inst: SkillInstance, spill = false): ItemInstance | null {\n    const item = makeSkillGemItem(inst);\n    if (!autoPlace(seat.meta.items, item)) {\n      if (spill) {\n        nativeHost.drops.push({\n          pos: nativeHost.clampPos(vec(seat.actor.pos.x + rand(-14, 14), seat.actor.pos.y + rand(-14, 14)), 10, undefined,\n            seat.actor.tier >= 1 ? { tier: seat.actor.tier } : undefined),\n          item: { kind: 'skill', inst }, bob: rand(0, Math.PI * 2), tier: seat.actor.tier, // THE SPOILS STORY: at the seat's feet\n        });\n        nativeHost.seatNote(seat, seat.actor.pos, 'your pack is full — it falls at your feet', '#c08a68', 12);\n        return null;\n      }\n      nativeHost.failNote(seat.actor, 'bagfull', 'inventory full');\n      return null;\n    }\n    nativeHost.markMetaDirty(seat);\n    return item;\n  }",
