      "source": "private evapDroveDress(t: number, rate: number): void {\n    for (const d of this.doodads) {\n      if (d.eventDress !== 'drove' || d.gone || d.evap) continue;\n      d.evap = { t, rate };\n      this.evaporating.push(d);\n    }\n  }",
      "output": "export function sceneEvapDroveDress(nativeHost:NativeSceneCampaignFrameClosureHost, t: number, rate: number): void {\n    for (const d of nativeHost.doodads) {\n      if (d.eventDress !== 'drove' || d.gone || d.evap) continue;\n      d.evap = { t, rate };\n      nativeHost.evaporating.push(d);\n    }\n  }",
