      "fn": "sceneDroveGathered",
      "line": 17403,
      "source": "private droveGathered(df: NonNullable<WorldSim['droveField']>, id: string, color: string, lvl: number): void {\n    const sc = this.droveScene;\n    const info = df.droveOn(this.zone.id);\n    if (sc && info) {\n      const cfg = df.surge();\n      const at = sc.penAt;\n      this.grantXp(cfg.reward.gatherXpBase + cfg.reward.gatherXpPerLevel * lvl, at); // XP BY PLACE\n      if (chance(cfg.reward.gemChance)) this.dropGemAt(at, undefined, true);\n      const pay = (tableId: string): void => {\n        for (const res of resolveLootTable(tableId, { ilvl: this.zone.level })) {\n          const p = this.clampPos(vec(at.x + rand(-26, 26), at.y + rand(-26, 26)), 10);\n          this.mintLootResult(p, res, true);\n        }\n      };\n      pay(cfg.reward.purseTable);\n      if (info.lost === 0 && info.penned > 0) {\n        pay(cfg.reward.flawlessTable);\n        this.text(vec(at.x, at.y - 44), 'every head alive — the flawless rate', color, 14);\n      }\n      if (sc.reeve && !sc.reeve.dead) {\n        this.text(vec(sc.reeve.pos.x, sc.reeve.pos.y - 28), 'That’s the lot. Dig in the chest.', color, 13);\n      }\n      this.evapDroveDress(45, 8); // the mended pen stands a while, then dries away\n      this.droveDressChecked = this.zone.id;\n    }\n    bumpLedger(this.ledger, 'droves_gathered');\n    this.notice('The fold is gathered — the reeve settles up.', color, 18, 'events');\n    df.resolve(id);\n    this.droveScene = null;\n  }",
      "output": "export function sceneDroveGathered(nativeHost:NativeSceneCampaignFrameClosureHost, df: NonNullable<WorldSim['droveField']>, id: string, color: string, lvl: number): void {\n    const sc = nativeHost.droveScene;\n    const info = df.droveOn(nativeHost.zone.id);\n    if (sc && info) {\n      const cfg = df.surge();\n      const at = sc.penAt;\n      nativeHost.grantXp(cfg.reward.gatherXpBase + cfg.reward.gatherXpPerLevel * lvl, at); // XP BY PLACE\n      if (chance(cfg.reward.gemChance)) nativeHost.dropGemAt(at, undefined, true);\n      const pay = (tableId: string): void => {\n        for (const res of resolveLootTable(tableId, { ilvl: nativeHost.zone.level })) {\n          const p = nativeHost.clampPos(vec(at.x + rand(-26, 26), at.y + rand(-26, 26)), 10);\n          nativeHost.mintLootResult(p, res, true);\n        }\n      };\n      pay(cfg.reward.purseTable);\n      if (info.lost === 0 && info.penned > 0) {\n        pay(cfg.reward.flawlessTable);\n        nativeHost.text(vec(at.x, at.y - 44), 'every head alive — the flawless rate', color, 14);\n      }\n      if (sc.reeve && !sc.reeve.dead) {\n        nativeHost.text(vec(sc.reeve.pos.x, sc.reeve.pos.y - 28), 'That’s the lot. Dig in the chest.', color, 13);\n      }\n      nativeHost.evapDroveDress(45, 8); // the mended pen stands a while, then dries away\n      nativeHost.droveDressChecked = nativeHost.zone.id;\n    }\n    bumpLedger(nativeHost.ledger, 'droves_gathered');\n    nativeHost.notice('The fold is gathered — the reeve settles up.', color, 18, 'events');\n    df.resolve(id);\n    nativeHost.droveScene = null;\n  }",
