      "fn": "sceneSpawnSwarmFlier",
      "line": 18415,
      "source": "private spawnSwarmFlier(info: SwarmInfo, cfg: SwarmingSurge): void {\n    if (!cfg.flightRoster.length) return;\n    const lvl = Math.max(1, this.zone.level + cfg.levelBonus);\n    const id = this.weightedPick(cfg.flightRoster, lvl);\n    if (!MONSTERS[id]) return;\n    const m = this.createMonster(id, lvl, 'enemy');\n    m.faction = info.faction;\n    m.tag = id === cfg.alateId ? 'swarm_alate' : 'swarm_flier';\n    const flow = this.bandFlow(info.dir);\n    m.pos = this.clampPos(vec(flow.entry.x + rand(-70, 70), flow.entry.y + rand(-70, 70)), m.radius);\n    this.actors.push(m);\n  }",
      "output": "export function sceneSpawnSwarmFlier(nativeHost:NativeSceneCampaignFrameClosureHost, info: SwarmInfo, cfg: SwarmingSurge): void {\n    if (!cfg.flightRoster.length) return;\n    const lvl = Math.max(1, nativeHost.zone.level + cfg.levelBonus);\n    const id = nativeHost.weightedPick(cfg.flightRoster, lvl);\n    if (!MONSTERS[id]) return;\n    const m = nativeHost.createMonster(id, lvl, 'enemy');\n    m.faction = info.faction;\n    m.tag = id === cfg.alateId ? 'swarm_alate' : 'swarm_flier';\n    const flow = nativeHost.bandFlow(info.dir);\n    m.pos = nativeHost.clampPos(vec(flow.entry.x + rand(-70, 70), flow.entry.y + rand(-70, 70)), m.radius);\n    nativeHost.actors.push(m);\n  }",
