      "source": "private brigandWanderPoint(): Vec2 {\n    return this.clampPos(vec(rand(80, this.arena.w - 80), rand(80, this.arena.h - 80)), 16);\n  }",
      "output": "export function sceneBrigandWanderPoint(nativeHost:NativeSceneCampaignFrameClosureHost): Vec2 {\n    return nativeHost.clampPos(vec(rand(80, nativeHost.arena.w - 80), rand(80, nativeHost.arena.h - 80)), 16);\n  }",
      "sourceSha256": "dfe5035b6bd4e4b0ca7efeae675cbe3de57ff5db3c11d2484d980a0c1286915d",
