      "source": "private updateDeedRecovery(): void {\n    this.bindCombatDeeds();\n    const p = this.player;\n    if (!this.metaProgressionActive() || p.dead || p.downed) { this.combatDeeds.reset(); return; }\n    if (this.combatDeeds.recovered(p.life, p.maxLife(), DEED_CFG.crisisRecover)) this.recordDeed({ kind: 'crisis' });\n  }",
      "output": "export function sceneUpdateDeedRecovery(nativeHost:NativeSceneCampaignFrameClosureHost): void {\n    nativeHost.bindCombatDeeds();\n    const p = nativeHost.player;\n    if (!nativeHost.metaProgressionActive() || p.dead || p.downed) { nativeHost.combatDeeds.reset(); return; }\n    if (nativeHost.combatDeeds.recovered(p.life, p.maxLife(), DEED_CFG.crisisRecover)) nativeHost.recordDeed({ kind: 'crisis' });\n  }",
