      "source": "private surfaceAnchor(): ZoneDef {\n    return !this.zone.dimension ? this.zone : (this.zoneMap[START_ZONE] ?? this.zone);\n  }",
      "output": "export function sceneSurfaceAnchor(nativeHost:NativeSceneCampaignFrameClosureHost): ZoneDef {\n    return !nativeHost.zone.dimension ? nativeHost.zone : (nativeHost.zoneMap[START_ZONE] ?? nativeHost.zone);\n  }",
