      "line": 12267,
      "source": "private triggerFracture(): void {\n    const run = this.fractureRun;\n    if (!run || run.phase !== 'dormant') return;\n    bumpLedger(this.ledger, 'fractures_seen'); // discovery — gates the Vault unlock\n    this.beginFissure(run, 'The earth splits — chase the fissure!');\n  }",
      "output": "export function sceneTriggerFracture(nativeHost:NativeSceneCampaignFrameClosureHost): void {\n    const run = nativeHost.fractureRun;\n    if (!run || run.phase !== 'dormant') return;\n    bumpLedger(nativeHost.ledger, 'fractures_seen'); // discovery — gates the Vault unlock\n    nativeHost.beginFissure(run, 'The earth splits — chase the fissure!');\n  }",
