      "source": "waypointBesieged(): boolean {\n    return this.zone.objective.kind === 'leyline' && !this.objectiveDone\n      && this.actors.some(a => !a.dead && a.tag === 'ley_siphon');\n  }",
      "output": "export function sceneWaypointBesieged(nativeHost:NativeSceneCampaignFrameClosureHost): boolean {\n    return nativeHost.zone.objective.kind === 'leyline' && !nativeHost.objectiveDone\n      && nativeHost.actors.some(a => !a.dead && a.tag === 'ley_siphon');\n  }",
