      "source": "private enterDemonRealm(invId: string, portalPos: Vec2): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep; solo keeps the old order.\n    const plan = this.demonRealmPlan(invId, portalPos);\n    if (!plan) return;\n    plan.context!(this);\n    plan.stamp!();\n    this.enterRealmArena(plan.arena);\n  }",
      "output": "export function sceneEnterDemonRealm(nativeHost:NativeSceneCampaignFrameClosureHost, invId: string, portalPos: Vec2): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep; solo keeps the old order.\n    const plan = nativeHost.demonRealmPlan(invId, portalPos);\n    if (!plan) return;\n    plan.context!(nativeHost);\n    plan.stamp!();\n    nativeHost.enterRealmArena(plan.arena);\n  }",
