      "source": "private realmRoad(make: (seat: Seat) => RoadTicket | null): Pick<RealmGateRow, 'road'> {\n    return this.shardWorld ? { road: make } : {};\n  }",
      "output": "export function sceneRealmRoad(nativeHost:NativeSceneCampaignFrameClosureHost, make: (seat: Seat) => RoadTicket | null): Pick<RealmGateRow, 'road'> {\n    return nativeHost.shardWorld ? { road: make } : {};\n  }",
