      "source": "private enterNecropolis(portalPos: Vec2): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep; solo keeps the old order.\n    const plan = this.necropolisRealmPlan(portalPos);\n    if (!plan) return;\n    plan.stamp!();\n    plan.context!(this);\n    this.necropolisPortals.length = 0;\n    this.enterRealmArena(plan.arena);\n  }",
      "output": "export function sceneEnterNecropolis(nativeHost:NativeSceneCampaignFrameClosureHost, portalPos: Vec2): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep; solo keeps the old order.\n    const plan = nativeHost.necropolisRealmPlan(portalPos);\n    if (!plan) return;\n    plan.stamp!();\n    plan.context!(nativeHost);\n    nativeHost.necropolisPortals.length = 0;\n    nativeHost.enterRealmArena(plan.arena);\n  }",
