      "source": "private enterCourtDomain(e: ActiveEncounter): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep (a court carries no context).\n    const plan = this.courtRealmPlan(e);\n    if (plan) this.enterRealmArena(plan.arena);\n  }",
      "output": "export function sceneEnterCourtDomain(nativeHost:NativeSceneCampaignFrameClosureHost, e: ActiveEncounter): void {\n    // THE REALM ROADS (shard M1 W4): the plan is the prep (a court carries no context).\n    const plan = nativeHost.courtRealmPlan(e);\n    if (plan) nativeHost.enterRealmArena(plan.arena);\n  }",
