      "source": "mimicSelectFor(sid: string, seat: Seat = this.localSeat): void {\n    mimicSelect(seat.actor, this.time, sid);\n  }",
      "output": "export function sceneMimicSelectFor(nativeHost:NativeSceneCampaignFrameClosureHost, sid: string, seat: Seat = nativeHost.localSeat): void {\n    mimicSelect(seat.actor, nativeHost.time, sid);\n  }",
