      "source": "levelUpSupport(gem: SupportInstance, seat: Seat = this.localSeat): boolean {\n    if (gem.level >= supportMaxLevel(gem.def)) return false;\n    if (!this.spendAbilityEssence(seat, supportLevelAbilityCost(gem.level + 1), 'abilvl:' + gem.def.id)) return false;\n    gem.level++;\n    this.charDirty = true;\n    return true;\n  }",
      "output": "export function sceneLevelUpSupport(nativeHost:NativeSceneCampaignFrameClosureHost, gem: SupportInstance, seat: Seat = nativeHost.localSeat): boolean {\n    if (gem.level >= supportMaxLevel(gem.def)) return false;\n    if (!nativeHost.spendAbilityEssence(seat, supportLevelAbilityCost(gem.level + 1), 'abilvl:' + gem.def.id)) return false;\n    gem.level++;\n    nativeHost.charDirty = true;\n    return true;\n  }",
