      "fn": "sceneSpendEssence",
      "line": 19621,
      "source": "private spendEssence(seat: Seat, cost: EssenceCost, noteKey: string): boolean {\n    if (!this.canAffordEssence(seat, cost)) {\n      this.failNote(seat.actor, noteKey, `needs ${cost.count}× ${ESSENCES[cost.essence].label}`);\n      return false;\n    }\n    seat.meta.essences[cost.essence] -= cost.count;\n    return true;\n  }",
      "output": "export function sceneSpendEssence(nativeHost:NativeSceneCampaignFrameClosureHost, seat: Seat, cost: EssenceCost, noteKey: string): boolean {\n    if (!nativeHost.canAffordEssence(seat, cost)) {\n      nativeHost.failNote(seat.actor, noteKey, `needs ${cost.count}× ${ESSENCES[cost.essence].label}`);\n      return false;\n    }\n    seat.meta.essences[cost.essence] -= cost.count;\n    return true;\n  }",
