      "fn": "sceneSalvageLane",
      "line": 41222,
      "source": "private salvageLane(seat: Seat, lane?: 'break' | 'sell'): 'break' | 'sell' | null {\n    const want = lane ?? (this.nearSalvage(seat) ? 'break' : 'sell');\n    if (want === 'break') return this.stationReach('salvage', seat) ? 'break' : null;\n    return this.nearScrapVendor(seat) ? 'sell' : null;\n  }",
      "output": "export function sceneSalvageLane(nativeHost:NativeSceneCampaignFrameClosureHost, seat: Seat, lane?: 'break' | 'sell'): 'break' | 'sell' | null {\n    const want = lane ?? (nativeHost.nearSalvage(seat) ? 'break' : 'sell');\n    if (want === 'break') return nativeHost.stationReach('salvage', seat) ? 'break' : null;\n    return nativeHost.nearScrapVendor(seat) ? 'sell' : null;\n  }",
