      "source": "private armBoroughFolk(folk: Actor): void {\n    if (folk.tag === 'borough_huddled') {\n      folk.tag = undefined;\n      this.text(vec(folk.pos.x, folk.pos.y - 38), 'armed!', '#e8c87a', 12);\n    }\n    folk.fillResources(); // re-seat life/mana so the graft shows immediately\n  }",
