      "fn": "sceneNearDelver",
      "line": 13478,
      "source": "nearDelver(seat: Seat = this.localSeat): boolean {\n    const site = this.descentSite;\n    if (!site || this.descentRun) return false;\n    return this.actors.some(a => a.id === site.delverId && !a.dead\n      && dist(a.pos, seat.actor.pos) <= DELVER_RADIUS\n      && this.dwellReachable(seat.actor.pos, a.pos, npcDwellReach('delver'), this.storyPair(seat.actor, a)));\n  }",
      "output": "export function sceneNearDelver(nativeHost:NativeSceneCampaignFrameClosureHost, seat: Seat = nativeHost.localSeat): boolean {\n    const site = nativeHost.descentSite;\n    if (!site || nativeHost.descentRun) return false;\n    return nativeHost.actors.some(a => a.id === site.delverId && !a.dead\n      && dist(a.pos, seat.actor.pos) <= DELVER_RADIUS\n      && nativeHost.dwellReachable(seat.actor.pos, a.pos, npcDwellReach('delver'), nativeHost.storyPair(seat.actor, a)));\n  }",
