      "fn": "sceneApplyPartyScale",
      "line": 5901,
      "source": "private applyPartyScale(a: Actor): void {\n    if (COOP_SCALING.shareRadius > 0 && a.pos.x === 0 && a.pos.y === 0) this.nearScaleDue.push(a); // keeperSeat: scaled at the placeholder, settled after the seat\n    return applyScenePartyScale(this.nativeScenePopulationHost(),a);\n  }",
      "output": "export function sceneApplyPartyScale(nativeHost:NativeSceneCampaignFrameClosureHost, a: Actor): void {\n    if (COOP_SCALING.shareRadius > 0 && a.pos.x === 0 && a.pos.y === 0) nativeHost.nearScaleDue.push(a); // keeperSeat: scaled at the placeholder, settled after the seat\n    return applyScenePartyScale(nativeHost.nativeScenePopulationHost(),a);\n  }",
