      "source": "export interface GrantedSkillRow {\n  def: SkillDef;\n  level: number;\n  inst: SkillInstance;\n  /** Who grants it — the first worn piece carrying the stat, else the passives. */\n  source: string;\n  /** The item whose grantState hosts the sockets (absent = passive-only grant). */\n  hostUid?: number;\n  /** Bar seat (0-based) the instance sits on; -1 while unseated (bar full). */\n  slot: number;\n}",
      "output": "export interface GrantedSkillRow {\n  def: SkillDef;\n  level: number;\n  inst: SkillInstance;\n  /** Who grants it — the first worn piece carrying the stat, else the passives. */\n  source: string;\n  /** The item whose grantState hosts the sockets (absent = passive-only grant). */\n  hostUid?: number;\n  /** Bar seat (0-based) the instance sits on; -1 while unseated (bar full). */\n  slot: number;\n}",
