      "output": "export interface WornGraftRow {\n  slot: number;             // 0-based bar index; speak it 1-based (\"Skill Slot N\")\n  def: SupportDef;\n  level: number;\n  skillId?: string;         // the skill bound at derivation time (absent = empty seat)\n  state: 'live' | 'duplicate' | 'unfit' | 'empty';\n}",
